export const LIQUIDITY_PAIRS_ALL_STRINGS: string[] = LIQUIDITY_POOLS_509.map((p) => p.pair);

export function getLiquidityPoolById(id: number): LiquidityPoolItem | undefined {
  return LIQUIDITY_POOLS_509.find((p) => p.id === id);
}

export function getLiquidityPoolsByCategory(categoryKey: string): LiquidityPoolItem[] {
  return LIQUIDITY_POOLS_509.filter((p) => p.categoryKey === categoryKey);
}

export function getRandomLiquidityPoolForChain(chain: string): LiquidityPoolItem {
  const normalized = chain.toLowerCase();
  let matches: LiquidityPoolItem[] = [];
  if (normalized.includes("base")) {
    matches = getLiquidityPoolsByCategory("base");
  } else if (normalized.includes("arbitrum")) {
    matches = getLiquidityPoolsByCategory("arbitrum");
  } else if (normalized.includes("optimism") || normalized.includes("op")) {
    matches = getLiquidityPoolsByCategory("optimism");
  } else if (normalized.includes("solana")) {
    matches = getLiquidityPoolsByCategory("solana");
  } else if (normalized.includes("bnb") || normalized.includes("binance")) {
    matches = getLiquidityPoolsByCategory("bnb");
  } else if (normalized.includes("polygon") || normalized.includes("avalanche")) {
    matches = getLiquidityPoolsByCategory("polygon_avalanche");
  } else if (normalized.includes("cosmos") || normalized.includes("atom")) {
    matches = getLiquidityPoolsByCategory("cosmos");
  } else if (normalized.includes("move") || normalized.includes("sui") || normalized.includes("aptos")) {
    matches = getLiquidityPoolsByCategory("move");
  } else if (normalized.includes("bitcoin") || normalized.includes("btc")) {
    matches = getLiquidityPoolsByCategory("btc_l2");
  } else {
    matches = getLiquidityPoolsByCategory("ethereum");
  }

  if (matches.length === 0) {
    return LIQUIDITY_POOLS_509[Math.floor(Math.random() * LIQUIDITY_POOLS_509.length)];
  }
  return matches[Math.floor(Math.random() * matches.length)];
}
